<?php require '../config/database.php'; require_once '../config/auth.php'; require_role('user'); $uid=$_SESSION['user_id']; $member_id=mysqli_fetch_assoc(mysqli_query($conn,"SELECT id FROM members WHERE user_id=$uid"))['id']; $recipes=mysqli_query($conn,"SELECT * FROM recipes"); ?>
<!DOCTYPE html><html><head><title>Meal Planner</title><link rel="stylesheet" href="../assets/css/style.css"><script src="../assets/js/app.js"></script></head><body><div class="layout"><?php include '_nav.php'; ?><main class="main"><h1>Diet & Meal Planning System</h1><p class="badge">Drag meal cards into your weekly planner</p><div class="grid" style="padding:20px 0"><?php $i=1; while($r=mysqli_fetch_assoc($recipes)):?><div id="meal<?=$i++?>" class="meal-item" draggable="true" ondragstart="dragStart(event)"><b><?=e($r['name'])?></b><br><?=$r['calories']?> cal • P<?=$r['protein']?> C<?=$r['carbs']?> F<?=$r['fats']?><br><small><?=e($r['goal'])?></small></div><?php endwhile;?></div><div class="meal-board"><?php foreach(['Mon','Tue','Wed','Thu','Fri','Sat','Sun'] as $d):?><div class="day" ondragover="allowDrop(event)" ondrop="dropMeal(event)"><h3><?=$d?></h3></div><?php endforeach;?></div><div class="card" style="margin-top:20px"><h2>Shopping List Generator</h2><p>Chicken breast, tuna, lettuce, oats, banana, milk, eggs, avocado, wheat bread, vegetables, rice.</p></div></main></div></body></html>
